// Responsive WebP variants are generated by scripts/prebuild-images.mjs into public/_img/.
// Original files keep their original paths; variants are only used for cards, hero and featured images.
import fs from 'node:fs';
import path from 'node:path';

export const VARIANT_WIDTHS = [400, 800, 1200] as const;
const PUBLIC_DIR = path.join(process.cwd(), 'public');

export type ImageSet = { src: string; srcSet?: string; sizes?: string };

/** `/posts/a.webp` -> `/_img/posts/a-800.webp` etc. Falls back to the original when no variant exists. */
export function imageSet(original: string | null, sizes: string, fallback = '/images/post-placeholder.webp'): ImageSet {
  const src = original || fallback;
  const base = src.replace(/\.[a-z0-9]+$/i, '');
  const found = VARIANT_WIDTHS.filter((w) => fs.existsSync(path.join(PUBLIC_DIR, '_img', `${base}-${w}.webp`)));
  if (!found.length) return { src };
  return {
    src: `/_img${base}-${found[Math.min(1, found.length - 1)]}.webp`,
    srcSet: found.map((w) => `/_img${base}-${w}.webp ${w}w`).join(', '),
    sizes,
  };
}
